apiPost(
        `/crm/calls/${id}/complete`,
        completeCrmCallSchema.parse({
          expectedVersion: version,
          completionNote: note,
        }),
        crmCallDetailSchema,
      )

apiPut(
            `/crm/contacts/${contact.id}`,
            {
              ...data,
              duplicateReviewed: reviewed,
              expectedVersion: contact.version,
            },
            crmContactDetailSchema,
          )

apiPost(
            '/crm/tasks',
            createCrmTaskSchema.parse({
              ...fields,
              interactionId: sourceId,
              prescriptionId: prescription || null,
              idempotencyKey: key,
            }),
            crmTaskDetailSchema,
          )

apiPost(
        `/crm/tasks/${id}/${action}`,
        action === 'escalate'
          ? escalateCrmTaskSchema.parse({
              expectedVersion: query.data!.task.version,
              reason,
            })
          : { expectedVersion: query.data!.task.version },
        crmTaskDetailSchema,
      )

apiPost(
                    '/finance/tills/preview',
                    { ...input, idempotencyKey: crypto.randomUUID() },
                    z.object({
                      expected: z.string(),
                      difference: z.string(),
                      paymentCount: z.number(),
                    }),
                  )

apiPut(
        "/hr/attendance",
        {
          workDate: date,
          entries: query.data?.map((r) => ({
            employeeId: r.employeeId,
            shiftTypeId: null,
            status: marks[r.employeeId] ?? r.status,
            minutesLate: 0,
            note: null,
          })),
        },
        attendanceSchema,
      )

apiGet(
        "/hr/on-duty",
        z.array(
          z.object({
            employeeId: z.string(),
            employeeName: z.string(),
            departmentId: z.string(),
            shiftName: z.string(),
            roleOnShift: z.string().nullable(),
          }),
        ),
      )

